                if( xCategoryAccess.is() && xCategoryAccess->hasByName( u"Label"_ustr ) && xCategoryAccess->hasByName( u"Effects"_ustr ) )
                {
                    OUString aLabel;
                    xCategoryAccess->getByName( u"Label"_ustr ) >>= aLabel;

                    Sequence< OUString > aEffects;
